exercises.solution:
const students = [];
function insert(row) {
  if (students.some(s => s.id === row.id)) {
    console.log("duplicate id");
    return;
  }
  students.push(row);
}
insert({ id: 1, name: "Ava" });
insert({ id: 1, name: "Ben" });
console.log("rows:", students.length);

