exercises.solution:
const students = [{ id: 1 }, { id: 2 }];
const enrollments = [];
function enroll(studentId, course) {
  if (!students.some(s => s.id === studentId)) {
    console.log("no such student");
    return;
  }
  enrollments.push({ studentId, course });
}
enroll(1, "CPRG 211");
enroll(9, "CPRG 211");
console.log("enrollments:", enrollments.length);
